1	package command
2	
3	import (
4		"errors"
5		"fmt"
6		"strconv"
7		"strings"
8		"time"
9	)
10	
11	// This file adds an optional declarative argument parser to the command
12	// package. It is deliberately independent of the command tree: a handler
13	// that wants parsing calls (*Parser).Parse on the raw args it receives; a
14	// handler that does not keeps receiving them verbatim. Node, Add, Execute
15	// and HandlerFunc are unaffected.
16	
17	// Sentinel errors describing parser-specification and parsing failures.
18	//
19	// Spec failures wrap ErrInvalidSpec in *SpecError; parse failures wrap one
20	// of the other sentinels in *ParseError. Callers distinguish classes with
21	// errors.Is and recover the offending spec name or raw token with
22	// errors.As.
23	var (
24		// ErrInvalidSpec indicates an illegal parser specification: an invalid
25		// or duplicated long or short option name, a default value that does
26		// not match the option type, more than one variadic positional
27		// argument, or a variadic argument that is not last. NewParser returns
28		// no usable parser when it is wrapped in the returned error.
29		ErrInvalidSpec = errors.New("command: invalid parser specification")
30	
31		// ErrUnknownOption indicates a token that looks like an option but
32		// matches neither a declared long nor short option. Tokens only become
33		// positional after a "--" separator.
34		ErrUnknownOption = errors.New("command: unknown option")
35	
36		// ErrMissingValue indicates an option that takes a value reached the
37		// end of the arguments without one.
38		ErrMissingValue = errors.New("command: missing option value")
39	
40		// ErrInvalidValue indicates an option value that could not be
41		// converted to the option's declared type.
42		ErrInvalidValue = errors.New("command: invalid option value")
43	
44		// ErrRequired indicates a required option was not provided on the
45		// command line (defaults never satisfy this) or a named positional
46		// argument was not supplied.
47		ErrRequired = errors.New("command: missing required argument")
48	
49		// ErrUnexpectedArgument indicates more positional tokens were given
50		// than the positional specification accepts.
51		ErrUnexpectedArgument = errors.New("command: unexpected positional argument")
52	)
53	
54	// ValueType selects the strong type applied to an option's values.
55	type ValueType int
56	
57	const (
58		// TypeString accepts any value unchanged.
59		TypeString ValueType = iota
60		// TypeBool parses values with strconv.ParseBool; a bare option spells
61		// true without consuming the next token.
62		TypeBool
63		// TypeInt parses decimal integers with strconv.Atoi (negatives
64		// included).
65		TypeInt
66		// TypeDuration parses values with time.ParseDuration (e.g. "500ms",
67		// "-2s").
68		TypeDuration
69	)
70	
71	// Option declares one command-line option.
72	//
73	// Long is the option's canonical name used after "--" and as the key for
74	// result lookups; it must be non-empty, contain only ASCII letters,
75	// digits, hyphens and underscores, and not start with a hyphen. Short is
76	// either empty (no short spelling) or a single ASCII letter or digit used
77	// after a single "-". Default holds the textual default value, interpreted
78	// according to Type; the empty string denotes the type's zero value and is
79	// always valid. Required marks the option as needing an explicit
80	// occurrence; a default never satisfies this. Repeatable allows the option
81	// to occur more than once, with every value retained in occurrence order;
82	// a non-repeatable option keeps the value of its last occurrence.
83	type Option struct {
84		Long       string
85		Short      string
86		Type       ValueType
87		Default    string
88		Required   bool
89		Repeatable bool
90	}
91	
92	// Positional declares one named positional argument. When Variadic is true
93	// the positional collects zero or more trailing tokens; at most one
94	// variadic positional is allowed and it must be the final positional. All
95	// non-variadic positionals are mandatory: missing one fails parsing with
96	// ErrRequired.
97	type Positional struct {
98		Name     string
99		Variadic bool
100	}
101	
102	// SpecError wraps ErrInvalidSpec and identifies the offending part of the
103	// specification.
104	type SpecError struct {
105		// Name is the offending option's long name or the positional name,
106		// when one is involved.
107		Name string
108		// Short is the offending short spelling, when one is involved.
109		Short string
110	
111		msg string
112	}
113	
114	func (e *SpecError) Error() string { return e.msg }
115	func (e *SpecError) Unwrap() error { return ErrInvalidSpec }
116	
117	// ParseError wraps one of the parse-time sentinels (ErrUnknownOption,
118	// ErrMissingValue, ErrInvalidValue, ErrRequired or
119	// ErrUnexpectedArgument).
120	type ParseError struct {
121		// Name is the canonical long option name or positional spec name the
122		// failure refers to. It is empty for an unknown option or an
123		// unexpected token, which by definition match no spec.
124		Name string
125		// Short is the short spelling of the option when the failure arose
126		// from a short cluster.
127		Short string
128		// Token is the raw command-line token involved: the unknown option
129		// token, the option token left without a value, or the surplus
130		// positional token.
131		Token string
132		// Value is the raw value text that failed type conversion, when
133		// applicable.
134		Value string
135	
136		kind error
137		msg  string
138	}
139	
140	func (e *ParseError) Error() string { return e.msg }
141	func (e *ParseError) Unwrap() error { return e.kind }
142	
143	// compiledOption is an Option plus its already-parsed default value.
144	type compiledOption struct {
145		Option
146		def any
147	}
148	
149	type compiledPositional struct {
150		Positional
151	}
152	
153	// Parser is an immutable, concurrency-safe compiled specification. A
154	// Parser may be shared across goroutines; each Parse call builds an
155	// independent Result and touches no process-level state.
156	type Parser struct {
157		options []compiledOption
158		args    []compiledPositional
159		long    map[string]*compiledOption
160		short   map[byte]*compiledOption
161	}
162	
163	// NewParser compiles options and positionals into a Parser. Both slices
164	// are copied, so later mutations by the caller cannot affect the parser.
165	// An invalid specification yields a *SpecError wrapping ErrInvalidSpec and
166	// a nil parser.
167	func NewParser(options []Option, positionals []Positional) (*Parser, error) {
168		p := &Parser{
169			options: make([]compiledOption, 0, len(options)),
170			args:    make([]compiledPositional, 0, len(positionals)),
171			long:    make(map[string]*compiledOption, len(options)),
172			short:   make(map[byte]*compiledOption, len(options)),
173		}
174	
175		seenLong := make(map[string]struct{}, len(options))
176		seenShort := make(map[byte]string, len(options))
177		for i := range options {
178			src := options[i]
179			if !validOptionName(src.Long) {
180				return nil, &SpecError{Name: src.Long, msg: fmt.Sprintf("command: invalid option name %q", src.Long)}
181			}
182			if _, dup := seenLong[src.Long]; dup {
183				return nil, &SpecError{Name: src.Long, msg: fmt.Sprintf("command: duplicate option %q", src.Long)}
184			}
185			if src.Short != "" {
186				if len(src.Short) != 1 || !isShortChar(src.Short[0]) {
187					return nil, &SpecError{Name: src.Long, Short: src.Short,
188						msg: fmt.Sprintf("command: invalid short option %q for option %q", src.Short, src.Long)}
189				}
190				if other, dup := seenShort[src.Short[0]]; dup {
191					return nil, &SpecError{Name: src.Long, Short: src.Short,
192						msg: fmt.Sprintf("command: short option %q already used by %q", src.Short, other)}
193				}
194			}
195			def, err := zeroOrConvert(src.Type, src.Default)
196			if err != nil {
197				return nil, &SpecError{Name: src.Long, Short: src.Short,
198					msg: fmt.Sprintf("command: invalid default %q for option %q: %v", src.Default, src.Long, err)}
199			}
200			p.options = append(p.options, compiledOption{Option: src, def: def})
201			seenLong[src.Long] = struct{}{}
202			if src.Short != "" {
203				seenShort[src.Short[0]] = src.Long
204			}
205		}
206		for i := range p.options {
207			co := &p.options[i]
208			p.long[co.Long] = co
209			if co.Short != "" {
210				p.short[co.Short[0]] = co
211			}
212		}
213	
214		seenPos := make(map[string]struct{}, len(positionals))
215		for i := range positionals {
216			src := positionals[i]
217			if src.Name == "" {
218				return nil, &SpecError{msg: "command: positional argument name must not be empty"}
219			}
220			if _, dup := seenPos[src.Name]; dup {
221				return nil, &SpecError{Name: src.Name, msg: fmt.Sprintf("command: duplicate positional argument %q", src.Name)}
222			}
223			seenPos[src.Name] = struct{}{}
224			p.args = append(p.args, compiledPositional{Positional: src})
225		}
226		// More-than-one variadic is reported at the second (and any later)
227		// variadic and takes priority over the not-last check.
228		if countVariadic(p.args) > 1 {
229			found := 0
230			for _, a := range p.args {
231				if !a.Variadic {
232					continue
233				}
234				found++
235				if found == 2 {
236					return nil, &SpecError{Name: a.Name,
237						msg: fmt.Sprintf("command: more than one variadic positional argument: %q", a.Name)}
238				}
239			}
240		}
241		for i, a := range p.args {
242			if a.Variadic && i != len(p.args)-1 {
243				return nil, &SpecError{Name: a.Name,
244					msg: fmt.Sprintf("command: variadic argument %q must be the last positional argument", a.Name)}
245			}
246		}
247	
248		return p, nil
249	}
250	
251	func countVariadic(args []compiledPositional) int {
252		n := 0
253		for _, a := range args {
254			if a.Variadic {
255				n++
256			}
257		}
258		return n
259	}
260	
261	// validOptionName mirrors the command-name character set: non-empty, no
262	// leading hyphen, ASCII letters, digits, hyphens and underscores.
263	func validOptionName(s string) bool {
264		if s == "" || s[0] == '-' {
265			return false
266		}
267		for i := 0; i < len(s); i++ {
268			switch c := s[i]; {
269			case c >= 'a' && c <= 'z':
270			case c >= 'A' && c <= 'Z':
271			case c >= '0' && c <= '9':
272			case c == '-' || c == '_':
273			default:
274				return false
275			}
276		}
277		return true
278	}
279	
280	func isShortChar(c byte) bool {
281		return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9'
282	}
283	
284	// zeroOrConvert converts textual values per t. The empty string yields the
285	// zero value, so an unset default is always representable.
286	func zeroOrConvert(t ValueType, raw string) (any, error) {
287		if raw == "" {
288			switch t {
289			case TypeString:
290				return "", nil
291			case TypeBool:
292				return false, nil
293			case TypeInt:
294				return 0, nil
295			case TypeDuration:
296				return time.Duration(0), nil
297			default:
298				return nil, fmt.Errorf("unknown value type %d", t)
299			}
300		}
301		return convertValue(t, raw)
302	}
303	
304	func convertValue(t ValueType, raw string) (any, error) {
305		switch t {
306		case TypeString:
307			return raw, nil
308		case TypeBool:
309			v, err := strconv.ParseBool(raw)
310			if err != nil {
311				return nil, err
312			}
313			return v, nil
314		case TypeInt:
315			v, err := strconv.Atoi(raw)
316			if err != nil {
317				return nil, err
318			}
319			return v, nil
320		case TypeDuration:
321			v, err := time.ParseDuration(raw)
322			if err != nil {
323				return nil, err
324			}
325			return v, nil
326		default:
327			return nil, fmt.Errorf("unknown value type %d", t)
328		}
329	}
330	
331	// Result holds one successful parse. Values are indexed by option long
332	// name; a Result is independent of every other Result and of the Parser.
333	type Result struct {
334		parser *Parser
335		// explicit holds the values supplied on the command line in
336		// occurrence order. A non-repeatable option's slice has length at most
337		// one and holds its last occurrence.
338		values map[string][]any
339		pos    []string
340	}
341	
342	// Parse decodes args according to the parser's specification. It never
343	// modifies args: long options accept both "--name=value" and
344	// "--name value", non-bool short options accept "-p value" (and the
345	// attached "-pvalue"/"-p=value" forms), short boolean options cluster as
346	// in "-vq", and everything after a standalone "--" token is positional.
347	// An option awaiting a value consumes the next token even when it begins
348	// with a hyphen, so negative integers and durations parse; an unknown
349	// hyphen-prefixed token never silently becomes positional.
350	//
351	// On failure the error is a *ParseError and the returned result is nil.
352	// An empty args slice still applies defaults and enforces required
353	// options and positionals.
354	func (p *Parser) Parse(args []string) (*Result, error) {
355		r := &Result{parser: p, values: make(map[string][]any)}
356	
357		onlyPositional := false
358		for i := 0; i < len(args); i++ {
359			token := args[i]
360	
361			if onlyPositional {
362				r.pos = append(r.pos, token)
363				continue
364			}
365			if token == "--" {
366				onlyPositional = true
367				continue
368			}
369	
370			switch {
371			case strings.HasPrefix(token, "--"):
372				if err := p.parseLong(token, args, &i, r); err != nil {
373					return nil, err
374				}
375			case len(token) > 1 && token[0] == '-':
376				if err := p.parseShort(token, args, &i, r); err != nil {
377					return nil, err
378				}
379			default:
380				// A bare "-" is an ordinary positional token.
381				r.pos = append(r.pos, token)
382			}
383		}
384	
385		if err := p.checkRequired(r); err != nil {
386			return nil, err
387		}
388		return r, nil
389	}
390	
391	func (p *Parser) parseLong(token string, args []string, i *int, r *Result) error {
392		body := token[2:]
393		name, raw, hasValue := strings.Cut(body, "=")
394		opt := p.long[name]
395		if opt == nil {
396			return &ParseError{Token: token, kind: ErrUnknownOption,
397				msg: fmt.Sprintf("command: unknown option %q", token)}
398		}
399	
400		if opt.Type == TypeBool {
401			if !hasValue {
402				r.record(opt, true)
403				return nil
404			}
405			b, err := strconv.ParseBool(raw)
406			if err != nil {
407				return &ParseError{Name: opt.Long, Token: token, Value: raw, kind: ErrInvalidValue,
408					msg: fmt.Sprintf("command: invalid value %q for option %q: %v", raw, opt.Long, err)}
409			}
410			r.record(opt, b)
411			return nil
412		}
413	
414		value, err := p.takeLongValue(opt, token, raw, hasValue, args, i)
415		if err != nil {
416			return err
417		}
418		converted, err := convertValue(opt.Type, value)
419		if err != nil {
420			return &ParseError{Name: opt.Long, Token: token, Value: value, kind: ErrInvalidValue,
421				msg: fmt.Sprintf("command: invalid value %q for option %q: %v", value, opt.Long, err)}
422		}
423		r.record(opt, converted)
424		return nil
425	}
426	
427	// takeLongValue returns the explicit "=" value or consumes the next token,
428	// even when it starts with a hyphen.
429	func (p *Parser) takeLongValue(opt *compiledOption, token, raw string, hasValue bool, args []string, i *int) (string, error) {
430		if hasValue {
431			return raw, nil
432		}
433		if *i+1 >= len(args) {
434			return "", &ParseError{Name: opt.Long, Token: token, kind: ErrMissingValue,
435				msg: fmt.Sprintf("command: option %q requires a value", opt.Long)}
436		}
437		*i++
438		return args[*i], nil
439	}
440	
441	func (p *Parser) parseShort(token string, args []string, i *int, r *Result) error {
442		for j := 1; j < len(token); j++ {
443			ch := token[j]
444			opt := p.short[ch]
445			if opt == nil {
446				return &ParseError{Token: token, kind: ErrUnknownOption,
447					msg: fmt.Sprintf("command: unknown option %q", token)}
448			}
449			if opt.Type == TypeBool {
450				r.record(opt, true)
451				continue
452			}
453	
454			var value string
455			if j+1 < len(token) {
456				// Attached value: -pvalue or -p=value; the remainder of the
457				// cluster belongs to this option regardless of content.
458				value = token[j+1:]
459				value = strings.TrimPrefix(value, "=")
460				j = len(token)
461			} else {
462				if *i+1 >= len(args) {
463					return &ParseError{Name: opt.Long, Short: opt.Short, Token: token, kind: ErrMissingValue,
464						msg: fmt.Sprintf("command: option %q requires a value", opt.Long)}
465				}
466				*i++
467				value = args[*i]
468			}
469			converted, err := convertValue(opt.Type, value)
470			if err != nil {
471				return &ParseError{Name: opt.Long, Short: opt.Short, Token: token, Value: value, kind: ErrInvalidValue,
472					msg: fmt.Sprintf("command: invalid value %q for option %q: %v", value, opt.Long, err)}
473			}
474			r.record(opt, converted)
475		}
476		return nil
477	}
478	
479	// record stores one explicit occurrence. Non-repeatable options keep only
480	// the last occurrence; repeatable options retain all of them in order.
481	func (r *Result) record(opt *compiledOption, value any) {
482		if !opt.Repeatable {
483			r.values[opt.Long] = []any{value}
484			return
485		}
486		r.values[opt.Long] = append(r.values[opt.Long], value)
487	}
488	
489	func (p *Parser) checkRequired(r *Result) error {
490		for i := range p.options {
491			opt := &p.options[i]
492			if opt.Required && len(r.values[opt.Long]) == 0 {
493				return &ParseError{Name: opt.Long, Short: opt.Short, kind: ErrRequired,
494					msg: fmt.Sprintf("command: missing required option %q", opt.Long)}
495			}
496		}
497	
498		n := len(p.args)
499		fixed := n
500		if n > 0 && p.args[n-1].Variadic {
501			fixed = n - 1
502		}
503		if len(r.pos) < fixed {
504			name := p.args[len(r.pos)].Name
505			return &ParseError{Name: name, kind: ErrRequired,
506				msg: fmt.Sprintf("command: missing required argument %q", name)}
507		}
508		if n == 0 || !p.args[n-1].Variadic {
509			if len(r.pos) > n {
510				return &ParseError{Token: r.pos[n], kind: ErrUnexpectedArgument,
511					msg: fmt.Sprintf("command: unexpected argument %q", r.pos[n])}
512			}
513		}
514		return nil
515	}
516	
517	// scalar returns the effective single value for an option: the last
518	// explicit occurrence, otherwise the parsed default (or the zero value).
519	// Unknown names yield nil.
520	func (r *Result) scalar(name string) any {
521		if vs, ok := r.values[name]; ok && len(vs) > 0 {
522			return vs[len(vs)-1]
523		}
524		if opt, ok := r.parser.long[name]; ok {
525			return opt.def
526		}
527		return nil
528	}
529	
530	// String returns the effective string value for the named option.
531	func (r *Result) String(name string) string {
532		v, _ := r.scalar(name).(string)
533		return v
534	}
535	
536	// Bool returns the effective bool value for the named option.
537	func (r *Result) Bool(name string) bool {
538		v, _ := r.scalar(name).(bool)
539		return v
540	}
541	
542	// Int returns the effective int value for the named option.
543	func (r *Result) Int(name string) int {
544		v, _ := r.scalar(name).(int)
545		return v
546	}
547	
548	// Duration returns the effective time.Duration value for the named option.
549	func (r *Result) Duration(name string) time.Duration {
550		v, _ := r.scalar(name).(time.Duration)
551		return v
552	}
553	
554	// Strings returns every explicitly provided string value for the named
555	// option in occurrence order. Defaults are not included; use String for
556	// the effective value.
557	func (r *Result) Strings(name string) []string {
558		out := make([]string, 0, len(r.values[name]))
559		for _, v := range r.values[name] {
560			if s, ok := v.(string); ok {
561				out = append(out, s)
562			}
563		}
564		return out
565	}
566	
567	// Bools returns every explicitly provided bool value for the named option
568	// in occurrence order. Defaults are not included.
569	func (r *Result) Bools(name string) []bool {
570		out := make([]bool, 0, len(r.values[name]))
571		for _, v := range r.values[name] {
572			if b, ok := v.(bool); ok {
573				out = append(out, b)
574			}
575		}
576		return out
577	}
578	
579	// Ints returns every explicitly provided int value for the named option in
580	// occurrence order. Defaults are not included.
581	func (r *Result) Ints(name string) []int {
582		out := make([]int, 0, len(r.values[name]))
583		for _, v := range r.values[name] {
584			if n, ok := v.(int); ok {
585				out = append(out, n)
586			}
587		}
588		return out
589	}
590	
591	// Durations returns every explicitly provided duration value for the named
592	// option in occurrence order. Defaults are not included.
593	func (r *Result) Durations(name string) []time.Duration {
594		out := make([]time.Duration, 0, len(r.values[name]))
595		for _, v := range r.values[name] {
596			if d, ok := v.(time.Duration); ok {
597				out = append(out, d)
598			}
599		}
600		return out
601	}
602	
603	// Provided reports whether the named option occurred explicitly on the
604	// command line. A value coming from a default reports false.
605	func (r *Result) Provided(name string) bool {
606		return len(r.values[name]) > 0
607	}
608	
609	// Count returns the number of explicit occurrences of the named option. A
610	// non-repeatable option provided at least once reports 1; a default-only
611	// option reports 0.
612	func (r *Result) Count(name string) int {
613		return len(r.values[name])
614	}
615	
616	// Args returns a copy of all positional tokens in command-line order,
617	// including the tokens collected by a trailing variadic argument.
618	func (r *Result) Args() []string {
619		return append([]string(nil), r.pos...)
620	}
621	
622	// NArg returns the number of positional tokens.
623	func (r *Result) NArg() int { return len(r.pos) }
624	
625	// Arg returns the value of the named non-variadic positional argument, or
626	// "" when no such fixed positional exists or it has no value. Use
627	// ArgValues for a variadic positional.
628	func (r *Result) Arg(name string) string {
629		for i, a := range r.parser.args {
630			if a.Name == name && !a.Variadic && i < len(r.pos) {
631				return r.pos[i]
632			}
633		}
634		return ""
635	}
636	
637	// ArgValues returns the values collected by the named variadic positional
638	// argument in order. It returns nil for a non-variadic or unknown name.
639	func (r *Result) ArgValues(name string) []string {
640		for i, a := range r.parser.args {
641			if a.Name == name && a.Variadic && i <= len(r.pos) {
642				return append([]string(nil), r.pos[i:]...)
643			}
