7	)
8	
9	// This file adds on-demand plain-text help to the command tree. Help is
10	// produced only through (*Node).WriteHelp: Execute never generates it, no
11	// implicit meaning is given to "--help" or "-h", and handlers still run
12	// exclusively from Execute.
13	
14	// WriteHelp writes plain-text help for the command path selects from n to w.
15	//
16	// path holds command segments resolved from n downward, one per level; an
17	// empty path (or nil) selects n itself. Segments match with the same exact,
18	// case-sensitive rules as Execute — primary names and aliases — and every
19	// resolved alias is rendered as the child's primary name, so the usage line
20	// always carries the canonical path. The path slice is never modified.
21	//
22	// parser is optional. With a nil parser only command information is shown.
23	// A non-nil parser adds "[options]" to the usage line when it declares
24	// options, followed by the positional specifications in declaration order
25	// ("<name>" for required positionals, "[<name>...]" for the variadic one),
26	// and contributes an Options section.
27	//
28	// Layout, independent of terminal width: the first line is "Usage: " plus
29	// the canonical path; when the selected node has children it gains
30	// "[command]" if the node carries a handler and "<command>" otherwise. A
31	// non-empty description follows verbatim after one blank line. Children
32	// appear in a "Commands:" section in Add order, each line carrying the
33	// primary name, aliases in registration order, and the description. Options
34	// appear in an "Options:" section in declaration order with their short and
35	// long names, a "<string>", "<int>" or "<duration>" placeholder for
36	// non-boolean options, and "(required)", "(repeatable)" and
37	// "(default: value)" markers as applicable. Sections are separated by
38	// exactly one blank line, every line ends with LF, the text ends with a
39	// single LF, and no ANSI sequences are emitted.
40	//
41	// If a path segment matches no child, WriteHelp returns a *LookupError
42	// wrapping ErrUnknownCommand; Path holds the canonical names resolved
43	// before the failure and Arg the original segment, and no byte reaches w.
44	// A write failure is returned unchanged; WriteHelp does not modify the
45	// tree, the parser, path, or any process state, never runs a handler, and
46	// is safe for concurrent use.
47	func (n *Node) WriteHelp(path []string, parser *Parser, w io.Writer) error {
48		current := n
49		canonical := []string{current.name}
50		for _, segment := range path {
51			next, ok := current.byName[segment]
52			if !ok {
53				resolved := make([]string, len(canonical))
54				copy(resolved, canonical)
55				return &LookupError{Path: resolved, Arg: segment}
56			}
57			current = next
58			canonical = append(canonical, next.name)
59		}
60	
61		var b strings.Builder
62		appendUsage(&b, canonical, current, parser)
63		if current.desc != "" {
64			b.WriteByte('\n')
65			b.WriteString(current.desc)
66			b.WriteByte('\n')
67		}
68		if len(current.children) > 0 {
69			appendCommands(&b, current)
70		}
71		if parser != nil && len(parser.options) > 0 {
72			appendOptions(&b, parser)
73		}
74	
75		_, err := io.WriteString(w, b.String())
76		return err
77	}
78	
79	// appendUsage writes the single "Usage:" line for the resolved node.
80	func appendUsage(b *strings.Builder, canonical []string, current *Node, parser *Parser) {
81		b.WriteString("Usage: ")
82		b.WriteString(strings.Join(canonical, " "))
83		if len(current.children) > 0 {
84			if current.handler != nil {
85				b.WriteString(" [command]")
86			} else {
87				b.WriteString(" <command>")
88			}
89		}
90		if parser != nil {
91			if len(parser.options) > 0 {
92				b.WriteString(" [options]")
93			}
94			for _, a := range parser.args {
95				if a.Variadic {
96					fmt.Fprintf(b, " [<%s>...]", a.Name)
97				} else {
98					fmt.Fprintf(b, " <%s>", a.Name)
99				}
100			}
101		}
102		b.WriteByte('\n')
103	}
104	
105	// appendCommands writes the "Commands:" section, children in Add order.
106	func appendCommands(b *strings.Builder, current *Node) {
107		b.WriteString("\nCommands:\n")
108		for _, child := range current.children {
109			b.WriteString("  ")
110			b.WriteString(child.name)
111			if len(child.aliases) > 0 {
112				b.WriteString(" (")
113				b.WriteString(strings.Join(child.aliases, ", "))
114				b.WriteByte(')')
115			}
116			if child.desc != "" {
117				b.WriteString("  ")
118				b.WriteString(child.desc)
119			}
120			b.WriteByte('\n')
121		}
122	}
123	
124	// appendOptions writes the "Options:" section in declaration order.
125	func appendOptions(b *strings.Builder, parser *Parser) {
126		b.WriteString("\nOptions:\n")
127		for i := range parser.options {
128			opt := &parser.options[i]
129			b.WriteString("  ")
130			if opt.Short != "" {
131				b.WriteByte('-')
132				b.WriteString(opt.Short)
133				b.WriteString(", ")
134			}
135			b.WriteString("--")
136			b.WriteString(opt.Long)
137			switch opt.Type {
138			case TypeString:
139				b.WriteString(" <string>")
140			case TypeInt:
141				b.WriteString(" <int>")
142			case TypeDuration:
143				b.WriteString(" <duration>")
144			}
145	
146			var markers []string
147			if opt.Required {
148				markers = append(markers, "required")
149			}
150			if opt.Repeatable {
151				markers = append(markers, "repeatable")
152			}
153			if opt.Default != "" {
154				markers = append(markers, "default: "+opt.Default)
155			}
156			if len(markers) > 0 {
157				b.WriteString("  (")
158				b.WriteString(strings.Join(markers, ", "))
159				b.WriteByte(')')
160			}
161			b.WriteByte('\n')
162		}
163	}
