27			{"short too long", []Option{{Long: "p", Short: "ab"}}, nil, "p"},
28			{"short hyphen", []Option{{Long: "p", Short: "-"}}, nil, "p"},
29			{"duplicate short", []Option{{Long: "a", Short: "x"}, {Long: "b", Short: "x"}}, nil, "b"},
