449		}
450		if got := r.ArgValues("args"); len(got) != 0 {
451			t.Fatalf("zero variadic values: %v", got)
452		}
453	
454		r, err = p.Parse([]string{"-f", "run", "x", "y", "--", "-z"})
455		if err != nil {
456			t.Fatal(err)
457		}
458		if r.Arg("cmd") != "run" {
459			t.Fatalf("cmd = %q", r.Arg("cmd"))
460		}
461		want := []string{"x", "y", "-z"}
462		if got := r.ArgValues("args"); !reflect.DeepEqual(got, want) {
463			t.Fatalf("variadic values = %v, want %v", got, want)
464		}
465	
466		// Variadic absorbs everything, so no surplus-argument error.
467		r, err = p.Parse([]string{"c", "1", "2", "3", "4", "5"})
468		if err != nil {
469			t.Fatal(err)
470		}
471		if r.NArg() != 6 {
472			t.Fatalf("NArg = %d, want 6", r.NArg())
473		}
474	}
475	
476	func TestFailureReturnsNoPartialResult(t *testing.T) {
477		p, _ := NewParser([]Option{{Long: "a"}, {Long: "b", Required: true}}, nil)
478		r, err := p.Parse([]string{"--a", "x", "--unknown"})
479		if err == nil {
480			t.Fatal("expected error")
481		}
482		if r != nil {
483			t.Fatalf("returned partial result %v on failure", r)
484		}
485		r, err = p.Parse([]string{"--a", "x"})
486		if err == nil || r != nil {
487			t.Fatalf("required failure must return nil result, got %v, %v", r, err)
488		}
489	}
490	
491	func TestParseDoesNotMutateInput(t *testing.T) {
492		p, _ := NewParser([]Option{{Long: "n", Short: "n", Type: TypeInt}, {Long: "v", Short: "v", Type: TypeBool}},
493			[]Positional{{Name: "rest", Variadic: true}})
494		argv := []string{"-v", "--n", "-3", "a", "--", "-x"}
495		original := append([]string(nil), argv...)
496		if _, err := p.Parse(argv); err != nil {
497			t.Fatal(err)
498		}
499		if !reflect.DeepEqual(argv, original) {
500			t.Fatalf("input mutated: %v, want %v", argv, original)
501		}
502	}
503	
504	func TestResultsAreIndependent(t *testing.T) {
505		p, _ := NewParser([]Option{{Long: "t", Repeatable: true}}, nil)
506		r1, err := p.Parse([]string{"--t", "a"})
507		if err != nil {
508			t.Fatal(err)
509		}
510		r2, err := p.Parse([]string{"--t", "b", "--t", "c"})
511		if err != nil {
512			t.Fatal(err)
513		}
514		if got := r1.Strings("t"); !reflect.DeepEqual(got, []string{"a"}) {
515			t.Fatalf("r1 contaminated by r2: %v", got)
516		}
517		if got := r2.Strings("t"); !reflect.DeepEqual(got, []string{"b", "c"}) {
518			t.Fatalf("r2 = %v", got)
519		}
520	}
521	
522	func TestParserConcurrentUse(t *testing.T) {
523		p, _ := NewParser([]Option{
524			{Long: "id", Type: TypeInt},
525			{Long: "tag", Repeatable: true},
526		}, []Positional{{Name: "rest", Variadic: true}})
527	
528		const goroutines = 32
529		const iterations = 100
530		var wg sync.WaitGroup
531		errCh := make(chan error, goroutines)
532		for g := 0; g < goroutines; g++ {
533			wg.Add(1)
534			go func(g int) {
535				defer wg.Done()
536				for i := 0; i < iterations; i++ {
537					argv := []string{"--id", fmt.Sprintf("%d", g), "--tag", "a", "x", "--", "-y"}
538					r, err := p.Parse(argv)
539					if err != nil {
540						errCh <- err
541						return
542					}
543					if r.Int("id") != g {
544						errCh <- fmt.Errorf("id = %d, want %d", r.Int("id"), g)
545						return
546					}
547					if got := r.Strings("tag"); !reflect.DeepEqual(got, []string{"a"}) {
548						errCh <- fmt.Errorf("tags = %v", got)
549						return
550					}
551					if got := r.ArgValues("rest"); !reflect.DeepEqual(got, []string{"x", "-y"}) {
552						errCh <- fmt.Errorf("rest = %v", got)
553						return
554					}
555				}
556			}(g)
557		}
558		wg.Wait()
559		close(errCh)
560		for err := range errCh {
561			t.Fatal(err)
562		}
563	}
564	
565	func TestEdgeCases(t *testing.T) {
566		// Explicit empty value is distinct from a default.
567		p, _ := NewParser([]Option{
568			{Long: "s", Type: TypeString, Default: "dflt"},
569			{Long: "n", Type: TypeInt},
570		}, nil)
571		r, err := p.Parse([]string{"--s=", "--n="})
572		if r != nil || !errors.Is(err, ErrInvalidValue) {
573			t.Fatalf("--n= should fail int conversion, got r=%v err=%v", r, err)
574		}
575		r, err = p.Parse([]string{"--s="})
576		if err != nil {
577			t.Fatal(err)
578		}
579		if r.String("s") != "" || !r.Provided("s") {
580			t.Fatalf("--s= should override default with explicit empty string, got %q provided=%v", r.String("s"), r.Provided("s"))
581		}
582	
583		// Repeated bools in one cluster accumulate on a repeatable bool.
584		pb, _ := NewParser([]Option{{Long: "v", Short: "v", Type: TypeBool, Repeatable: true}}, nil)
585		rb, err := pb.Parse([]string{"-vvv"})
586		if err != nil {
587			t.Fatal(err)
588		}
589		if rb.Count("v") != 3 || len(rb.Bools("v")) != 3 {
590			t.Fatalf("count = %d bools = %v", rb.Count("v"), rb.Bools("v"))
591		}
592	
593		// Standalone "--" with no positionals.
594		pp, _ := NewParser(nil, nil)
595		rp, err := pp.Parse([]string{"--"})
596		if err != nil || rp.NArg() != 0 {
597			t.Fatalf("bare --: err=%v narg=%d", err, rp.NArg())
598		}
599	
600		// Unknown names read as zero values without panicking.
601		re, err := NewParser(nil, nil)
602		if err != nil {
603			t.Fatal(err)
604		}
605		rr, err := re.Parse(nil)
606		if err != nil {
607			t.Fatal(err)
608		}
609		if rr.String("nope") != "" || rr.Int("nope") != 0 || rr.Bool("nope") || rr.Duration("nope") != 0 {
610			t.Fatal("unknown option accessor must yield zero values")
611		}
612		if rr.Provided("nope") || rr.Count("nope") != 0 {
613			t.Fatal("unknown option must not report as provided")
614		}
615	}
616	
617	func TestParserIntegratesWithCommandTree(t *testing.T) {
618		// A handler that opts into parsing.
619		p, err := NewParser([]Option{{Long: "port", Type: TypeInt, Default: "8080"}},
620			[]Positional{{Name: "path"}})
621		if err != nil {
622			t.Fatal(err)
623		}
624		var parsed *Result
625		parsingHandler := func(path []string, args []string, stdout, stderr io.Writer) error {
626			r, err := p.Parse(args)
627			if err != nil {
628				return err
629			}
630			parsed = r
631			return nil
632		}
633	
634		root := New("tool", "", nil, nil)
635		if err := root.Add(New("serve", "", []string{"s"}, parsingHandler)); err != nil {
636			t.Fatal(err)
637		}
638		if err := root.Execute(context.Background(),
639			[]string{"s", "--port", "9090", "/x"}, io.Discard, io.Discard); err != nil {
640			t.Fatal(err)
641		}
642		if parsed.Int("port") != 9090 || parsed.Arg("path") != "/x" {
643			t.Fatalf("port=%d path=%q", parsed.Int("port"), parsed.Arg("path"))
644		}
645	
646		// Parse errors propagate through Execute unchanged.
647		err = root.Execute(context.Background(), []string{"serve", "--bogus"}, io.Discard, io.Discard)
648		if !errors.Is(err, ErrUnknownOption) {
649			t.Fatalf("err = %v, want ErrUnknownOption", err)
650		}
651	
652		// Defaults apply inside the handler when the option is omitted.
653		parsed = nil
654		if err := root.Execute(context.Background(), []string{"serve", "/y"}, io.Discard, io.Discard); err != nil {
655			t.Fatal(err)
656		}
657		if parsed == nil || parsed.Int("port") != 8080 || parsed.Arg("path") != "/y" {
658			t.Fatalf("default not applied: %v", parsed)
659		}
660	
661		// A handler that does not opt in still receives untouched raw args,
662		// including option-like tokens.
663		var raw []string
664		legacy := New("legacy", "", nil, func(path []string, as []string, stdout, stderr io.Writer) error {
665			raw = append([]string(nil), as...)
666			return nil
667		})
668		var stdout, stderr bytes.Buffer
669		if err := legacy.Execute(context.Background(),
670			[]string{"--anything", "-x", "val"}, &stdout, &stderr); err != nil {
671			t.Fatal(err)
672		}
673		if want := []string{"--anything", "-x", "val"}; !reflect.DeepEqual(raw, want) {
674			t.Fatalf("legacy handler args = %v, want %v", raw, want)
675		}
676	}
