		"run a server\n" +
		"\n" +
		"Commands:\n" +
		"  stop  stop the server\n" +
		"\n" +
		"Options:\n" +
		"  -l, --level <int>  (default: 2)\n"
	if got != want {
		t.Errorf("help =\n%q\nwant\n%q", got, want)
